/**
 * The Cloudflare Worker entry: the Next.js app (built by OpenNext) plus the
 * daily Cron Trigger (wrangler.jsonc → triggers.crons), which calls the same
 * /api/cron/weekly route Vercel Cron used, with CRON_SECRET as the proof.
 */
// Generated by `opennextjs-cloudflare build` (bundled by Wrangler; not type-checked).
import { default as handler } from "../.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
}

export default {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const req = new Request("https://scheduled.internal/api/cron/weekly", {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}`, "user-agent": "cloudflare-cron" },
    });
    ctx.waitUntil(
      Promise.resolve(handler.fetch(req, env, ctx)).then(async (res: Response) => {
        console.log("weekly search", res.status, await res.text());
      }),
    );
  },
};
